def solve_mode_simple(grid):
    result = []
    for i in range(4):
        row = []
        for j in range(4):
            counts = {}
            for r in range(3):
                for c in range(3):
                    v = grid[i*3+r][j*3+c]
                    counts[v] = counts.get(v, 0) + 1
            max_c = max(counts.values())
            modes = [k for k,v in counts.items() if v == max_c]
            row.append(modes[0])
        result.append(row)
    return result

def solve_mode_min_tiebreak(grid):
    result = []
    for i in range(4):
        row = []
        for j in range(4):
            counts = {}
            for r in range(3):
                for c in range(3):
                    v = grid[i*3+r][j*3+c]
                    counts[v] = counts.get(v, 0) + 1
            max_c = max(counts.values())
            modes = sorted([k for k,v in counts.items() if v == max_c])
            row.append(modes[0])
        result.append(row)
    return result

def solve_count3_minority(grid):
    """When majority has count divisible by 3 (like 3,6), pick minority"""
    result = []
    for i in range(4):
        row = []
        for j in range(4):
            counts = {}
            for r in range(3):
                for c in range(3):
                    v = grid[i*3+r][j*3+c]
                    counts[v] = counts.get(v, 0) + 1

            div3_counts = [v for v,c in counts.items() if c % 3 == 0 and c > 1]

            if len(div3_counts) == 1:
                other = [v for v in counts.keys() if v not in div3_counts]
                if other:
                    row.append(other[0])
                else:
                    row.append(min(counts.keys()))
            else:
                max_c = max(counts.values())
                modes = sorted([k for k,v in counts.items() if v == max_c])
                row.append(modes[0])
        result.append(row)
    return result

